SELECT T_A.* , CRYPTO_DEC('normal', T_A.CREATED_BY_ENC, '', 0) AS CREATED_BY , CRYPTO_DEC('normal', T_A.IP_ENC, '', 0) AS IP , CRYPTO_DEC('normal', T_A.UPDATED_BY_ENC, '', 0) AS UPDATED_BY FROM ( SELECT A.ID , A.CREATED_AT , A.UPDATED_AT , A.CREATED_AT_TEXT , A.CREATED_BY AS CREATED_BY_ENC , A.IP AS IP_ENC , A.ITEM_NAME , I.OPTIONS , I.TEXT_OPTION , A.ITEM_SEQUENCE , A.LOG_TYPE , A.ORDER_CODE , A.ORDER_SEQUENCE , A.ORDER_STATUS , A.ORG_ORDER_STATUS , A.UPDATED_AT_TEXT , A.UPDATED_BY AS UPDATED_BY_ENC , A.USER_TYPE FROM OP_ORDER_LOG A , OP_ORDER_ITEM I , OP_SELLER S WHERE A.ORDER_CODE = I.ORDER_CODE AND A.ORDER_SEQUENCE = I.ORDER_SEQUENCE AND A.ITEM_SEQUENCE = I.ITEM_SEQUENCE AND I.SELLER_ID = S.SELLER_ID AND A.ORDER_CODE = #{orderCode}
AND S.SELLER_ID = #{sellerId}
AND S.LOCGOV_CODE = #{shLocgovCode}
AND I.LOCGOV_CODE = #{shLocgovCode}
ORDER BY I.OPTIONS, A.ITEM_NAME, A.CREATED_AT DESC ) T_A

